function NotaAutoguardada({ notaId, textoInicial }) {
  const [texto, setTexto] = useState(textoInicial);

  useEffect(() => {
    setInterval(() => {
      fetch(`/api/notas/${notaId}`, {
        method: 'PUT',
        body: JSON.stringify({ texto }),
      });
    }, 5000);
  }, [notaId]);

  return <textarea value={texto} onChange={(e) => setTexto(e.target.value)} />;
}
